}

.studio-metric__value {
  font-size: 1.5rem;
  font-weight: 700;
  margin-top: 4px;
}

.studio-metric__delta {
  font-size: 0.75rem;
  color: var(--studio-green);
  margin-top: 2px;
}

.studio-tabs__list {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  border-bottom: 1px solid var(--studio-border);
  margin-bottom: 16px;
}

.studio-tab {
  background: transparent;
  border: none;
  color: var(--studio-muted);
